{
  "case_id": "xsu_sg_010_congenital_impairment_documentation",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret nævner journaludskrifter, epikriser, speciallægeudtalelser, personlig beskrivelse som supplement og at SU kan bede om mere dokumentation. Det siger dog ikke, at sygehistorik og de seneste foreliggende lægeoplysninger er centrale, og det siger ikke, at de seneste oplysninger kan være ældre. Det tilføjer også, at materialet 'så vidt muligt' skal beskrive aktuelle følger, især begrænsning i muligheden for at arbejde. Det er en let forskydning i forhold til vejledningen, som fremhæver sygehistorik og udrednings-/behandlingsforløb. Samlet er der ingen grove fejl, men svaret rammer ikke rubrikkens hovedpunkt tilstrækkeligt."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Mangler eksplicit sygehistorik og de seneste foreliggende lægeoplysninger. Mangler også udrednings- og behandlingsforløb. Støtteforanstaltninger og skånehensyn nævnes slet ikke. Personlig redegørelse nævnes som supplement, men ikke at den navnlig bruges, hvor forholdene ikke er dokumenteret. Epikriser og journalnotater nævnes som eksempler."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret handler direkte om, hvilken dokumentation en ansøger med medfødt funktionsnedsættelse kan vedlægge, og giver konkrete eksempler."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret henviser ikke til nogen identificerbar kilde som lov, bekendtgørelse eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Ingen kilde er angivet, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Ingen kilde er angivet, så støtten til de enkelte påstande kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer, at materialet 'så vidt muligt' skal beskrive de aktuelle følger, især begrænsningen i muligheden for at arbejde ved siden af studiet. Det understøttes ikke direkte af afsnit 4.3, som vægter sygehistorik og seneste journalnotater. Det kan dog delvist støttes af bekendtgørelsens § 36 og § 37, stk. 4. Svaret nævner også 'udtalelse fra egen læge' og 'undersøgelses- eller testresultater', som ikke er nævnt i vejledningsafsnittet. Egen læge er nævnt i § 37, stk. 3. Tilføjelserne er derfor kun delvist problematiske."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret fastholder ikke, at de seneste foreliggende oplysninger kan være ældre, og at eksemplerne ikke er kumulative krav. Det siger heller ikke, at den personlige redegørelse ikke ophæver det lægefaglige minimum. Det siger kun, at den ikke erstatter lægefaglige oplysninger, og det dækker delvist det sidste punkt."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende: eksempler på dokumentation, rollen for barndomsdokumenter, aktuelle følger, personlig beskrivelse som supplement og mulighed for anmodning om mere dokumentation."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "Svaret bruger 'kan', 'fx' og 'så vidt muligt' og gør ikke eksemplerne obligatoriske. Det siger, at personlig beskrivelse ikke erstatter lægefaglige oplysninger, hvilket er i overensstemmelse med rubrikken. 'SU kan bede om' svarer til § 37, stk. 5."
    }
  },
  "xhaile_coverage": {
    "A49": {
      "label": "partial",
      "reason": "Svaret behandler medfødt funktionsnedsættelse og at barndomsdokumenter kan vise, at tilstanden er medfødt. Det nævner personlig beskrivelse som supplement. Det nævner ikke, at nyere dokumentation ofte mangler, at sygehistorik og seneste journalnotater er særligt vigtige, eller at eksempellisten ikke er udtømmende."
    },
    "A35": {
      "label": "partial",
      "reason": "Svaret nævner epikriser, journaludskrifter og personlig beskrivelse som supplement. Det nævner ikke udrednings- og behandlingsforløb, de seneste lægefaglige oplysninger, afgørelser om støtte eller skånehensyn, og heller ikke at redegørelsen især bruges, når dokumentation mangler."
    }
  },
  "overall_notes": "Svaret er praktisk og relevant, men angiver ingen kilder og mangler flere kritiske elementer: sygehistorik og seneste foreliggende oplysninger, udrednings- og behandlingsforløb, støtteforanstaltninger og skånehensyn samt forbeholdet om, at de seneste oplysninger kan være ældre. Der er ingen grove juridiske fejl, og svaret fastholder, at personlig beskrivelse ikke erstatter lægefaglige oplysninger. Fordi der ikke er kilder, er C04 not_met og C05 og C06 not_assessable."
}

